            case 'rouge':
                this.couleur = 'vert';
                break;
            case 'vert':
                this.couleur = 'orange';
                break;
            case 'orange':
                this.couleur = 'rouge';
                break;
        }
    }
}

function convertirBase(n, base) {
    if (n === 0) return '0';
    const chiffres = [];
    while (n > 0) {
        const reste = n % base;
        chiffres.unshift(reste < 10 ? reste.toString() : String.fromCharCode(87 + reste));
        n = Math.floor(n / base);
    }
    return chiffres.join('');
}

function kemePlusGrand(tab, k) {
    const distincts = [...new Set(tab)];
    distincts.sort((a, b) => b - a);
    if (k > 0 && k <= distincts.length) {
        return distincts[k - 1];
    }
    return undefined;
}

function compteurFrequence(tab) {
    const frequence = {};
    for (const element of tab) {
        frequence[element] = (frequence[element] || 0) + 1;
    }
    return frequence;
}

function exponentiationRapide(x, n) {
    if (n === 0) return 1;
    const temp = exponentiationRapide(x, Math.floor(n / 2));
    if (n % 2 === 0) {
        return temp * temp;
    } else {
        return x * temp * temp;
    }
}

function sousTableauMax(tab) {
    let maxActuel = tab[0];
    let maxGlobal = tab[0];
    for (let i = 1; i < tab.length; i++) {
        maxActuel = Math.max(tab[i], maxActuel + tab[i]);
        if (maxActuel > maxGlobal) {
            maxGlobal = maxActuel;
        }
    }
    return maxGlobal;
}
